import re

_TITLE_RE = re.compile(r"<title>(.*?)</title>", re.IGNORECASE | re.DOTALL)


def title_of(html: str) -> str:
    """Return the text between the first `<title>` and the next `</title>`.

    Tag names match case-insensitively. The text is returned exactly as it
    appears: no whitespace stripping and no entity decoding. Returns "" if
    there is no `<title>`, or if it has no closing `</title>` after it.
    No network access is used; `html` is already fetched.
    """
    m = _TITLE_RE.search(html)
    return m.group(1) if m else ""


def test_basic_title() -> None:
    html = "<html><head><title>Hello</title></head><body></body></html>"
    assert title_of(html) == "Hello"


def test_no_title_returns_empty() -> None:
    assert title_of("<html><body>No title here</body></html>") == ""
    assert title_of("") == ""


def test_empty_title_element() -> None:
    assert title_of("<title></title>") == ""


def test_missing_closing_tag() -> None:
    assert title_of("<html><title>Unclosed<body></body></html>") == ""


def test_closing_tag_without_opening() -> None:
    assert title_of("<html>oops</title></html>") == ""


def test_case_insensitive_tags() -> None:
    assert title_of("<TITLE>Upper</TITLE>") == "Upper"
    assert title_of("<Title>Mixed</tItLe>") == "Mixed"


def test_first_title_wins() -> None:
    assert title_of("<title>One</title><title>Two</title>") == "One"


def test_whitespace_and_newlines_preserved() -> None:
    assert title_of("<title>\n  Spaced out \n</title>") == "\n  Spaced out \n"


def test_entities_not_decoded() -> None:
    assert title_of("<title>Tom &amp; Jerry</title>") == "Tom &amp; Jerry"


def test_title_text_with_other_markup_chars() -> None:
    assert title_of("<title>a < b > c</title>") == "a < b > c"


def test_closing_tag_before_opening_is_ignored() -> None:
    assert title_of("</title><title>Real</title>") == "Real"

